    public Task<RespuestaLlm> CompletarAsync(SolicitudLlm solicitud, CancellationToken cancellationToken)
    {
        int numero;
        lock (_candado)
        {
            numero = _solicitudes.Count;
            _solicitudes.Add(solicitud);
        }

        return Task.FromResult(_guion(solicitud, numero));
    }

