        herramientas
            .Where(h => estudianteId is not null || !h.Parametros.Any(p => p.Nombre == ParametroEstudianteId))
            .Select(h => Llamada($"llamada-{h.Nombre}", h.Nombre, ArgumentosPara(h, estudianteId)))
