    private const decimal CaracteresPorToken = 3.5m;
    private const decimal ProporcionMinimaDelContexto = 0.75m;
    private const decimal ProporcionRealMaxima = 1.04m;
    private const int TopeDeTokensEstimados = 3000;
    private const string Pregunta = "¿Cuál es mi promedio ponderado del periodo?";
    private const string Respuesta = "Tu promedio es 4.39.";
    private const string LlaveDeOpenAi = "[llave-redactada]";

    public static TheoryData<string, string?, int, bool> ReportesDelProveedor => new()
    {
        { "e2", null, 0, false },
        { "e3", null, 1, false },
        { "e4", null, 2, false }
    };

    private static int Estimar(PeticionLlm peticion)
    {
        using var cuerpo = JsonDocument.Parse(peticion.Cuerpo);
        var caracteres = cuerpo.RootElement.GetProperty("messages").EnumerateArray().Sum(m => CaracteresDe(m.GetProperty("content")));
        return (int)Math.Ceiling(caracteres / CaracteresPorToken);
    }

    private static int CaracteresDe(JsonElement contenido) =>
        contenido.ValueKind switch
        {
            JsonValueKind.String => contenido.GetString()!.Length,
            JsonValueKind.Array => contenido.EnumerateArray().Sum(parte => parte.TryGetProperty("text", out var texto) ? texto.GetString()!.Length : 0),
            _ => 0
        };

    private static int Reportado(int estimado, int caso) =>
        caso switch
        {
            0 => (int)Math.Ceiling(ProporcionMinimaDelContexto * estimado),
            1 => (int)Math.Floor(ProporcionRealMaxima * estimado),
            _ => 0
        };

