        var reportado = 0;
        var manejador = new ManejadorLlmFalso((peticion, _) =>
        {
            estimado = Estimar(peticion);
            reportado = (int)Math.Ceiling(ProporcionMinimaDelContexto * estimado) - 1;
            return RespuestasProveedor.Texto(peticion, Respuesta, reportado, 5);
        });
