using System.Text.Json;
using TutorFlow.Core.Asistente;

namespace TutorFlow.Api.Tests.Dobles;

public static class ConsumoRealista
{
    private const decimal CaracteresPorToken = 3.5m;
    private const decimal FactorReal = 1.04m;

    public static int Estimados(SolicitudLlm solicitud) =>
        Estimados(solicitud.PromptSistema.Length + solicitud.Mensajes.Sum(m => m.Contenido.Length));

    public static int Reportados(SolicitudLlm solicitud) => Reportados(Estimados(solicitud));

    public static int Estimados(PeticionLlm peticion)
    {
        using var cuerpo = JsonDocument.Parse(peticion.Cuerpo);
        var raiz = cuerpo.RootElement;
        var caracteres = raiz.GetProperty("messages").EnumerateArray().Sum(m => CaracteresDe(m.GetProperty("content")));
        return Estimados(raiz.TryGetProperty("system", out var sistema) ? caracteres + CaracteresDe(sistema) : caracteres);
    }

    public static int Reportados(PeticionLlm peticion) => Reportados(Estimados(peticion));

    public static int Reportados(int estimados) => (int)Math.Ceiling(FactorReal * estimados);

    public static int TokensDe(SolicitudLlm solicitud, int salida) => Reportados(solicitud) + salida;

    public static int TokensDe(IEnumerable<SolicitudLlm> solicitudes, int salida) => solicitudes.Sum(s => TokensDe(s, salida));

    public static int TokensDe(IEnumerable<PeticionLlm> peticiones, int salida) => peticiones.Sum(p => Reportados(p) + salida);

    public static decimal CostoDe(int entrada, int salida, decimal precioEntrada, decimal precioSalida) =>
        (entrada * precioEntrada + salida * precioSalida) / 1_000_000m;

    private static int Estimados(int caracteres) => (int)Math.Ceiling(caracteres / CaracteresPorToken);

    private static int CaracteresDe(JsonElement contenido) =>
        contenido.ValueKind switch
        {
            JsonValueKind.String => contenido.GetString()!.Length,
            JsonValueKind.Array => contenido.EnumerateArray().Sum(CaracteresDe),
            JsonValueKind.Object => contenido.TryGetProperty("text", out var texto) ? CaracteresDe(texto)
                : contenido.TryGetProperty("content", out var anidado) ? CaracteresDe(anidado) : 0,
            _ => 0
        };
}
