namespace TutorFlow.Api.Tests.Operacion;

public sealed class PresupuestoSinPrecioApiTests
{
    private const string PresupuestoDiario = "0.03";
    private const string ClaveReserva = "Llm:ReservaSinPrecioUsd";
    private const string Pregunta = "¿Cuál es mi promedio?";
    private const int TokensPorPeticion = 1200;
    private const int PeticionesPorEscenario = 4;
    private const int Aceptadas = 3;
    private static readonly UsoTokens Uso = new(1000, 200);

    public static TheoryData<string?> ReservasQueSeUsanPorDefecto => new()
    {
        "0.01",
        null,
        "0",
        "-0.5",
        "abc"
    };

    private static Dictionary<string, string?> Configuracion(string? reserva)
    {
        var configuracion = new Dictionary<string, string?> { ["Limites:PresupuestoDiarioUsd"] = PresupuestoDiario };
        if (reserva is not null)
        {
            configuracion[ClaveReserva] = reserva;
        }

        return configuracion;
    }

    private static Dictionary<string, string?> ModeloSinPrecio() =>
        new() { ["LLM_API_KEY"] = "sk-abc", ["LLM_MODELO"] = "modelo-sin-precio" };

    private static ClienteLlmDoble LlmDeLaPrueba() => ClienteLlmDoble.Texto("Tu promedio es 4.39.", Uso);

    private static async Task<IReadOnlyList<RespuestaApi>> PreguntarSeguidoAsync(FabricaApi fabrica)
    {
        var respuestas = new List<RespuestaApi>();
        for (var i = 0; i < PeticionesPorEscenario; i++)
        {
            respuestas.Add(await fabrica.PreguntarEstudianteAsync("EST-001", Pregunta));
        }

        return respuestas;
    }

    [Theory]
    [MemberData(nameof(ReservasQueSeUsanPorDefecto))]
    [Trait("CA", "CA-11")]
    [Trait("CA", "CA-07")]
    [Trait("ESC", "ESC-180")]
    [Trait("SEG", "SEG-13")]
    public async Task ESC_180_Un_modelo_sin_precio_reserva_001_por_peticion_y_la_cuarta_da_503_sin_llamar_al_llm(string? reserva)
    {
        var llm = LlmDeLaPrueba();
        using var fabrica = new FabricaApi(llm: llm, configuracion: Configuracion(reserva), variablesEntorno: ModeloSinPrecio());

        var respuestas = await PreguntarSeguidoAsync(fabrica);

        Assert.Equal([200, 200, 200, 503], respuestas.Select(r => r.Estado).ToArray());
        Assert.All(respuestas.Take(Aceptadas), r =>
        {
            Assert.Equal(TokensPorPeticion, r.Tokens);
            Assert.Equal(0m, r.CostoUsd);
        });
        Assert.Equal(Aceptadas, llm.Llamadas);
        Assert.All(fabrica.Auditoria.Eventos.Take(Aceptadas), e => Assert.True(e.PrecioDesconocido));
    }

    [Theory]
    [InlineData("0")]
    [InlineData("-0.5")]
    [InlineData("abc")]
    [Trait("CA", "CA-11")]
    [Trait("ESC", "ESC-180")]
    [Trait("SEG", "SEG-13")]
    public async Task ESC_180_Una_reserva_sin_precio_invalida_se_ignora_con_una_advertencia_al_arrancar(string reserva)
    {
        using var fabrica = new FabricaApi(llm: LlmDeLaPrueba(), configuracion: Configuracion(reserva), variablesEntorno: ModeloSinPrecio());

        await PreguntarSeguidoAsync(fabrica);

        Assert.Contains(fabrica.Logs.Mensajes, m => m.Contains("ReservaSinPrecioUsd", StringComparison.Ordinal));
    }

    private const int TokensPorLlamada = 120;
    private const decimal CostoPorLlamada = 0.00002m;

    public static TheoryData<string, string> BloqueosSinReintento => new()
    {
        { "SEG-10b-nombre-ajeno", "Andres Martinez sacó 2.6 en Cálculo" },
        { "SEG-10b-id-inventado", "EST 099 tiene un promedio de 4.39." }
    };

    [Fact]
    [Trait("CA", "CA-21")]
    [Trait("ESC", "ESC-193")]
    [Trait("RF", "SEG-10c")]
    public async Task ESC_193b_El_reintento_se_entrega_con_los_tokens_y_el_costo_de_los_dos_turnos_y_reintento_true_en_la_auditoria()
    {
        var llm = GuionesPorTurno.Texto("Tu promedio es 4.40.", "Tu promedio es 4.39.");
        using var fabrica = new FabricaApi(llm: llm, configuracion: FabricaApi.Precios("0.10", "0.50"), conocimientoReal: true);

        var respuesta = await fabrica.PreguntarEstudianteAsync("EST-001", PreguntaPromedio);

        Assert.Equal(200, respuesta.Estado);
        Afirmaciones.SalidaDelContrato(respuesta);
        Assert.Equal("Tu promedio es 4.39.", respuesta.Respuesta);
        Assert.Equal(2, fabrica.Llm.Llamadas);
        Assert.Equal(2 * TokensPorLlamada, respuesta.Tokens);
        Assert.Equal(2 * CostoPorLlamada, respuesta.CostoUsd);
        Assert.True(respuesta.UsoDatosEstudiante);
        var evento = Assert.Single(fabrica.Auditoria.Eventos);
        Assert.Equal(ResultadoAuditoria.Respondida, evento.Resultado);
        Assert.Equal(2 * TokensPorLlamada, evento.Tokens);
        AfirmacionesDeReintento.AfirmarReintentoRegistrado(evento);
    }

    [Fact]
    [Trait("CA", "CA-21")]
    [Trait("ESC", "ESC-193")]
    [Trait("RF", "SEG-10f")]
    public async Task ESC_193a_El_coordinador_recibe_el_texto_del_reintento_con_un_solo_segundo_turno()
    {
        var llm = GuionesPorTurno.LeeElProgramaYResponde(PerdidaDeMateo, PerdidasDeValentina);
        using var fabrica = new FabricaApi(llm: llm, conocimientoReal: true);

        var respuesta = await fabrica.PreguntarCoordinadorAsync("COORD-02", PreguntaQ10Seis);

        Assert.Equal(200, respuesta.Estado);
        Assert.Equal(PerdidasDeValentina, respuesta.Respuesta);

